WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, new_group_flag, session_no, CASE WHEN merchant RLIKE '^(7-Eleven|Lazada)$' THEN 'OTHER_ZONE' WHEN merchant RLIKE '^(Grab|Amazon)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS merchant_zone FROM islands ORDER BY id DESC NULLS FIRST, amount
